/* tools/node/mkbundle.js — THE RULES OF ONE BUILD as a single Node module (v1.01 wave 2, Phase D1 → Phase E's verifier loads it).
   Writes server/verify/rules.js: the stub page (tools/node/dom.js + page.js, inlined) + the built page's static markup (styles cut) +
   its script, byte for byte; and server/verify/rules.json {v, build, bytes, at}. build = the first 12 hex of sha256(the script) — the
   same number `node tools/node/mkbundle.js --hash` prints for any page, so a match played on build X is checked by the rules of build X.
   server/verify/ is NOT part of the online server zip (server/src) and never part of the browser page; rules.js is generated (git-ignored).
     node tools/node/mkbundle.js [page=flavius-arena.html] [--out dir] [--hash]
   Use:  const R = require('./server/verify/rules.js');  const P = await R.open({ls, t0});   (P = tools/node/page.js's openGame result)
         R.page = {markup, code} (for tools/node/replay.js: replayGolden(G, {page: R.page}))  R.build, R.v */
'use strict';
const fs=require('fs'),path=require('path'),crypto=require('crypto');
const {splitPage}=require('./page.js');
const ROOT=path.resolve(__dirname,'..','..');
const buildHash=code=>crypto.createHash('sha256').update(code).digest('hex').slice(0,12);
function bundle(pageFile,outDir){const html=fs.readFileSync(pageFile,'utf8');const {markup,code}=splitPage(html);
  const v=(markup.match(/arena · v([0-9.]+)/)||code.match(/arena · v([0-9.]+)/)||[])[1]||'?';const build=buildHash(code);
  /* the markup the rules need: every element (ids, data-*); styles, fonts and the language loader are dropped */
  const mk=markup.replace(/<style\b[\s\S]*?<\/style>/gi,'').replace(/<script\b[\s\S]*?<\/script>/gi,'').replace(/<link\b[^>]*>/gi,'');
  const src=f=>fs.readFileSync(path.join(__dirname,f),'utf8');
  const out=`/* server/verify/rules.js — GENERATED by tools/node/mkbundle.js from ${path.basename(pageFile)} — do not edit (edit tools/node/*).
   The rules of build ${build} (v${v}) for Node: the game's own script in a stub page (tools/node/dom.js + page.js). */
'use strict';
const __dom=(()=>{const module={exports:{}};
${src('dom.js')}
return module.exports})();
const __page=(require=>{const module={exports:{}};
${src('page.js')}
return module.exports})(n=>n==='./dom.js'?__dom:require(n));
const page={markup:${JSON.stringify(mk)},code:${JSON.stringify(code)}};
module.exports={v:${JSON.stringify(v)},build:${JSON.stringify(build)},page,open:(o={})=>__page.openGame({...o,page})};
`;
  fs.mkdirSync(outDir,{recursive:true});const f=path.join(outDir,'rules.js');fs.writeFileSync(f,out);
  const meta={v,build,bytes:Buffer.byteLength(out),at:new Date().toISOString()};fs.writeFileSync(path.join(outDir,'rules.json'),JSON.stringify(meta)+'\n');
  return {file:f,...meta}}
module.exports={bundle,buildHash};
if(require.main===module){const a=process.argv.slice(2);const oi=a.indexOf('--out');const outDir=oi>=0?path.resolve(a[oi+1]):path.join(ROOT,'server','verify');
  const page=path.resolve(a.find(x=>/\.html$/.test(x))||path.join(ROOT,'flavius-arena.html'));
  if(a.includes('--hash')){console.log(buildHash(splitPage(fs.readFileSync(page,'utf8')).code));process.exit(0)}
  const r=bundle(page,outDir);console.log(`rules of build ${r.build} (v${r.v}) → ${path.relative(process.cwd(),r.file)} · ${(r.bytes/1048576).toFixed(2)} MB`)}
